        s=re.sub(r'/assets/js/(?:committee-tables|dvtlf|jbpf|jcvf|jeff-pac|jfc|jmf|jvf|schumer-committee)\.js','/assets/js/committee-receipts.js',s)
        start=s.find('<details class="original-receipts"')
        disclosure='<details class="original-receipts"><summary>Original receipt records and memos</summary></details>'
        if start>=0:
            end=s.rfind('</details>')
            assert end>start,p
            s=s[:start]+disclosure+s[end+len('</details>'):]
        else:
            s=s.replace('<footer',disclosure+'<footer',1)
